package com.jackbhai.omnitools.nativ.games;

import android.content.Context;
import android.graphics.Canvas;
import android.view.MotionEvent;

import com.jackbhai.omnitools.nativ.Glass;

import java.util.Random;

/** Lights Out: tap a light to toggle it and its neighbours. Turn every
 *  light off in as few moves as you can. Boards are generated by random
 *  presses, so they are always solvable. */
public final class LightsOutView extends BaseGameView {
    private final Random rnd = new Random();
    private LightsOutLogic g;
    private int presses = 8;
    private String level = "Medium";

    public LightsOutView(Context c) { super(c); newGame(); }

    private void newGame() { g = new LightsOutLogic(rnd, presses); }

    @Override protected void update(long dt) {}
    @Override protected void drawGame(Canvas cv) {
        float w = getWidth(), pad = dp(16);
        boolean done = g.isSolved() && g.moves() > 0;
        leftText(cv, "Lights Out    " + level + "  •  Moves: " + g.moves(), pad, dp(34), 15, Glass.TEXT, true);
        leftText(cv, "Tap: [Level]  [New Game]", pad, dp(58), 12, Glass.NEON_CYAN, false);
        String bestKey = "lightsout_best_" + level;
        String st = done ? "All lights out — solved in " + g.moves()
                : "Lights on: " + g.litCount() + (best(bestKey) > 0 ? "   •   Best: " + best(bestKey) : "");
        leftText(cv, st, pad, dp(84), 14, Glass.TEXT_DIM, false);
        float board = Math.min(w - pad * 2, getHeight() - dp(140));
        float x0 = (w - board) / 2, y0 = dp(104), cell = board / LightsOutLogic.N;
        for (int r = 0; r < LightsOutLogic.N; r++) for (int c = 0; c < LightsOutLogic.N; c++) {
            float l = x0 + c * cell + dp(3), t = y0 + r * cell + dp(3);
            float rr = l + cell - dp(6), bb = t + cell - dp(6);
            if (g.get(r, c)) {
                roundRect(cv, l, t, rr, bb, dp(12), Glass.NEON_CYAN);
            } else glassCell(cv, l, t, rr, bb, dp(12));
        }
    }

    @Override public boolean onTouchEvent(MotionEvent e) {
        if (e.getAction() != MotionEvent.ACTION_UP) return true;
        float w = getWidth();
        if (e.getY() >= dp(44) && e.getY() < dp(70)) {
            if (e.getX() < w * 0.5f) {
                if (presses == 8) { presses = 12; level = "Hard"; }
                else if (presses == 12) { presses = 5; level = "Easy"; }
                else { presses = 8; level = "Medium"; }
            }
            newGame(); invalidate(); return true;
        }
        float pad = dp(16);
        float board = Math.min(w - pad * 2, getHeight() - dp(140));
        float x0 = (w - board) / 2, y0 = dp(104), cell = board / LightsOutLogic.N;
        int c = (int) ((e.getX() - x0) / cell), r = (int) ((e.getY() - y0) / cell);
        if (r < 0 || r >= LightsOutLogic.N || c < 0 || c >= LightsOutLogic.N) return true;
        g.press(r, c);
        if (g.isSolved()) {
            String key = "lightsout_best_" + level;
            if (best(key) == 0 || g.moves() < best(key)) saveInt(key, g.moves());
        }
        invalidate();
        return true;
    }
}
